  const noterFait = n => { const m = memoire(); if (!(niv in m.faits) || n < m.faits[niv]) m.faits[niv] = n; try { localStorage.setItem(CLE, JSON.stringify(m)); } catch (_) {} };
  const lire = s => { const [p, c, m] = s.split(':'); return { plaques: p.split('.').map(Number), cible: +c, min: +m }; };
  function charger(jour) { niv = +q('#cb-niv').value; duJour = jour; const B = BANQUE[niv], j = aujourdhui().n; let k = ((j % B.length) + B.length) % B.length;
    if (!jour) { let t; do { t = Math.floor(Math.random() * B.length); } while (t === k || (pb && B[t] === pb.src)); k = t; }
    pb = lire(B[k]); pb.src = B[k]; raz(); }
  function raz() { items = pb.plaques.map((v, i) => ({ v, pris: false, plaque: true })); lignes = []; cur = { a: -1, op: '', b: -1 }; msg = ''; cl = ''; indice = 0; gagne = false; vu = false; q('#cb-sol').hidden = true; rendre(); }
  const libres = () => items.filter(x => !x.pris).map(x => x.v);
